    public static int itFind(emon.Port.Cells nodes, int kind, int nth) {
        // The nth node (from 0) of the kind, -1 when there are not so many.
        int n = Model.nodeCount(nodes);
        int i = 0;
        int seen = 0;
        while (i < n) {
            if (Model.nodeKind(nodes, i) == kind) {
                if (seen == nth) {
                    return i;
                }
                seen += 1;
            }
            i += 1;
        }
        return -1;
    }
    public static int itSays(emon.Port.Cells text, int start, int n, byte[] b) {
        // 1 when the run text[start, start+n) is the ASCII text b.
        int i = 0;
        if (n != emon.Port.blobLen(b)) {
            return 0;
        }
        while (i < emon.Port.blobLen(b)) {
            if (emon.Port.cellsAt(text, start + i) != emon.Port.blobU8(b, i)) {
                return 0;
            }
            i += 1;
        }
        return 1;
    }
