    public static void testWordsOfOtherFontsAreSpans() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells gl = emon.Port.newCells();
        emon.Port.Cells ift = emon.Port.newCells();
        emon.Port.Cells an = emon.Port.newCells();
        emon.Port.Cells txt = emon.Port.newCells();
        emon.Port.Cells nodes = emon.Port.newCells();
        emon.Port.Cells attrs = emon.Port.newCells();
        emon.Port.Cells regions = emon.Port.newCells();
        emon.Port.Cells text = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells ledger = emon.Port.newCells();
        emon.Port.Cells layout = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        itBody(wd, ln, et, emon.Testport.textBlob("alpha beta gamma delta epsilon"));
        itFonts(ift);
        // the second line is words 6..10: beta (7) is bold, gamma (8) and delta (9) are italic, epsilon (10) bold
        Evidence.wdSet(wd, 7, Evidence.wfFont(), 1);
        Evidence.wdSet(wd, 8, Evidence.wfFont(), 2);
        Evidence.wdSet(wd, 9, Evidence.wfFont(), 2);
        Evidence.wdSet(wd, 10, Evidence.wfFont(), 1);
        itBuild(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout);
        int p = itFind(nodes, Model.nkParagraph(), 0);
        int s0 = itFind(nodes, Model.nkSpan(), 0);
        int s1 = itFind(nodes, Model.nkSpan(), 1);
        int s2 = itFind(nodes, Model.nkSpan(), 2);
        int c0 = Model.nodeFirstChild(nodes, s0);
        int c1 = Model.nodeFirstChild(nodes, s1);
        int c2 = Model.nodeFirstChild(nodes, s2);
        int pf = Model.nodeFirstChild(nodes, p);
        int n0 = Model.nodeNext(nodes, s0);
        int n2 = Model.nodeNext(nodes, s2);
        emon.Testport.assertEq(itFind(nodes, Model.nkParagraph(), 1), -1, "one paragraph");
        emon.Testport.assertEq(itFind(nodes, Model.nkSpan(), 3), -1, "and three spans in it: bold, italic (two words, one span), bold");
        emon.Testport.assertEq(Model.nodeParent(nodes, s0), p, "the first is a child of the paragraph");
        emon.Testport.assertEq(Model.nodeSub(nodes, s0), 1, "bold");
        emon.Testport.assertEq(Model.nodeSub(nodes, s1), 2, "italic");
        emon.Testport.assertEq(Model.nodeSub(nodes, s2), 1, "bold");
        emon.Testport.assertEq(itOwn(nodes, text, c0, emon.Testport.textBlob("beta")), 1, "beta");
        emon.Testport.assertEq(itOwn(nodes, text, c1, emon.Testport.textBlob("gamma delta")), 1, "gamma delta: the space between them is inside the span");
        emon.Testport.assertEq(itOwn(nodes, text, c2, emon.Testport.textBlob("epsilon")), 1, "epsilon");
        emon.Testport.assertEq(itOwn(nodes, text, pf, emon.Testport.textBlob("lorem ipsum dolor sit amet consectetur alpha ")), 1, "the first text is the line before and `alpha`, and the space before the span is outside it");
        emon.Testport.assertEq(itOwn(nodes, text, n0, emon.Testport.textBlob(" ")), 1, "the space between bold and italic is plain");
        emon.Testport.assertEq(itOwn(nodes, text, n2, emon.Testport.textBlob(" lorem ipsum dolor sit amet consectetur")), 1, "and the text after the last span goes on");
        emon.Testport.assertEq(Model.modelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "a Model in document order");
    }
